"""Replay real generated bytes and validate calls without loading model weights.

These are parser checks, not new neural generations or maintenance scores.
"""

import copy
import importlib.util
import json
from pathlib import Path
import unittest

ROOT = Path(__file__).resolve().parents[1]
SPEC = importlib.util.spec_from_file_location(
    "cpu_model_service_under_test", ROOT / "benchmarks/cpu_model_service.py"
)
SERVICE = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(SERVICE)
EOS = "<|im_end|>"
TOOLS = [
    {
        "type": "function",
        "function": {
            "name": "read_file",
            "parameters": {
                "type": "object",
                "properties": {
                    "file_path": {"type": "string", "minLength": 1},
                    "offset": {"type": "integer", "minimum": 0},
                },
                "required": ["file_path"],
            },
        },
    }
]


@unittest.skipUnless(
    importlib.util.find_spec("jsonschema"), "Install CPU runtime requirements"
)
class CpuToolParserTests(unittest.TestCase):
    def setUp(self):
        self.validators = SERVICE.declared_tools(TOOLS)

    def parse(self, text, mode="json-object-compat"):
        return SERVICE.parse_output(text, EOS, self.validators, mode)

    def tagged(self, value):
        return "<tool_call>" + json.dumps(value) + "</tool_call>"

    def call(self, **arguments):
        return {"name": "read_file", "arguments": arguments}

    def test_recorded_neural_output_requires_explicit_compatibility(self):
        raw = (
            ROOT
            / "evidence/cpu-model/int8/responses/1776907efdc84a249154676e1e08a46d.text"
        ).read_text()
        content, calls, error = self.parse(raw, "native")
        self.assertEqual(calls, [])
        self.assertIsNone(error)
        self.assertTrue(content.startswith("("))
        content, calls, error = self.parse(raw)
        self.assertEqual((content, error), ("", None))
        self.assertEqual(len(calls), 1)
        self.assertEqual(calls[0]["function"]["name"], "read_file")
        self.assertEqual(
            json.loads(calls[0]["function"]["arguments"]), {"file_path": "/sample.py"}
        )

    def test_original_time_censored_maintenance_outputs_remain_non_calls(self):
        for variant, ids in {
            "fp32": [
                "376afceee0fc48adacf78b9b2701e79c",
                "e61f2bf091374272b0ff64d77754faf0",
            ],
            "int8": [
                "4b4f7fa0dd274b23b61b611680fee700",
                "20b9393d7c4b449bbe81ad4f75689e8d",
            ],
        }.items():
            for request_id in ids:
                with self.subTest(request_id=request_id):
                    raw = (
                        ROOT
                        / f"evidence/cpu-model/{variant}/responses/{request_id}.text"
                    ).read_text()
                    self.assertEqual(self.parse(raw)[1], [])

    def test_native_multiple_calls_preserve_prose_and_literal_tags(self):
        one = self.tagged(self.call(file_path="/a<tool_call></tool_call>.py"))
        two = self.tagged(self.call(file_path="/b.py", offset=0))
        content, calls, error = self.parse(
            "Inspect\n" + one + "\n" + two + EOS, "native"
        )
        self.assertEqual((content, error), ("Inspect", None))
        self.assertEqual(len(calls), 2)
        self.assertNotEqual(calls[0]["id"], calls[1]["id"])
        self.assertIn(
            "<tool_call>", json.loads(calls[0]["function"]["arguments"])["file_path"]
        )

    def test_bare_object_and_legacy_argument_string_are_supported(self):
        value = self.call(file_path="/sample.py")
        value["arguments"] = json.dumps(value["arguments"])
        self.assertEqual(len(self.parse(json.dumps(value))[1]), 1)

    def test_literal_native_tags_inside_complete_compat_json_are_argument_text(self):
        value = self.call(file_path="/a<tool_call></tool_call>.py")
        for raw in [json.dumps(value), "(" + json.dumps(value) + ")"]:
            content, calls, error = self.parse(raw)
            self.assertEqual((content, error), ("", None))
            self.assertEqual(
                json.loads(calls[0]["function"]["arguments"]), value["arguments"]
            )

    def test_fresh_neural_call_and_failed_final_response_replay(self):
        service = ROOT / "evidence/tool-compat/outputs/cpu-model-20261120-03"
        first = (service / "f503c97b18a54d399b9851f3fd71193e.text").read_text()
        second = (service / "2cf0c81b8b804d0688eff63e178a0ad2.text").read_text()
        self.assertEqual(len(self.parse(first)[1]), 1)
        self.assertEqual(self.parse(second), ("None", [], None))

    def test_never_extract_from_prose_markdown_arrays_or_schema_documents(self):
        payload = json.dumps(self.call(file_path="/sample.py"))
        for raw in [
            "Example: " + payload,
            "```json\n" + payload + "\n```",
            "[" + payload + "]",
            json.dumps(TOOLS[0]),
        ]:
            with self.subTest(raw=raw):
                self.assertEqual(self.parse(raw)[1], [])

    def test_invalid_or_partial_framing_cannot_execute_even_valid_prefix(self):
        valid = self.tagged(self.call(file_path="/sample.py"))
        for raw in [
            valid + "<tool_call>{",
            "</tool_call>" + valid,
            valid + "</tool_call>",
            "(" + json.dumps(self.call(file_path="/sample.py")),
            valid[:-1],
            valid + "<tool_call>NaN</tool_call>",
        ]:
            with self.subTest(raw=raw):
                self.assertEqual(self.parse(raw)[1:], ([], "invalid_tool_json"))

    def test_unknown_function_rejects_entire_native_batch(self):
        raw = self.tagged(self.call(file_path="/sample.py")) + self.tagged(
            {"name": "execute", "arguments": {"command": "ignored"}}
        )
        self.assertEqual(self.parse(raw)[1:], ([], "undeclared_tool"))

    def test_required_type_bounds_and_unlisted_arguments_are_checked(self):
        for arguments in [
            {},
            {"file_path": 42},
            {"file_path": ""},
            {"file_path": "/a", "offset": -1},
            {"file_path": "/a", "offset": True},
            {"file_path": "/a", "command": "ignored"},
        ]:
            with self.subTest(arguments=arguments):
                self.assertEqual(
                    self.parse(self.tagged(self.call(**arguments)))[1:],
                    ([], "invalid_tool_arguments"),
                )

    def test_duplicate_keys_nonfinite_numbers_and_extra_envelope_keys_rejected(self):
        for payload in [
            '{"name":"read_file","name":"execute","arguments":{}}',
            '{"name":"read_file","arguments":{"file_path":"/a","file_path":"/b"}}',
            '{"name":"read_file","arguments":{"file_path":"/a","offset":NaN}}',
            '{"name":"read_file","arguments":{"file_path":"/a","offset":1e999}}',
            '{"name":"read_file","arguments":{"file_path":"/a"},"example":true}',
        ]:
            for raw in [payload, "<tool_call>" + payload + "</tool_call>"]:
                with self.subTest(raw=raw):
                    self.assertEqual(self.parse(raw)[1:], ([], "invalid_tool_json"))

    def test_declared_schema_local_references_and_nested_requirements(self):
        tools = copy.deepcopy(TOOLS)
        schema = tools[0]["function"]["parameters"]
        schema["$defs"] = {"path": {"type": "string", "pattern": "^/"}}
        schema["properties"]["file_path"] = {"$ref": "#/$defs/path"}
        validators = SERVICE.declared_tools(tools)
        for path, count in [("/sample.py", 1), ("relative.py", 0)]:
            calls = SERVICE.parse_output(
                self.tagged(self.call(file_path=path)), EOS, validators
            )[1]
            self.assertEqual(len(calls), count)

    def test_request_schemas_reject_duplicates_and_external_references(self):
        with self.assertRaises(ValueError):
            SERVICE.declared_tools(TOOLS + TOOLS)
        tools = copy.deepcopy(TOOLS)
        tools[0]["function"]["parameters"]["properties"]["file_path"] = {
            "$ref": "https://example.invalid/schema"
        }
        with self.assertRaises(ValueError):
            SERVICE.declared_tools(tools)

    def test_no_declared_tools_cannot_be_called(self):
        raw = self.tagged(self.call(file_path="/sample.py"))
        self.assertEqual(SERVICE.parse_output(raw, EOS)[1:], ([], "undeclared_tool"))


if __name__ == "__main__":
    unittest.main()
